const BANK=[{"id": 0, "d": "01", "page": 12, "source": "GCT501_01_Culture and Technology.pdf", "term": "Edward Tylor", "stem": "Who is associated with culture as “that complex whole”?", "answer": "Edward Tylor", "wrong": ["Geert Hofstede", "Ernst Kapp", "Don Ihde"], "keys": [], "image": null, "kind": "concept", "quote": "“Culture ... is that complex whole which includes knowledge, belief, art, morals, law, custom, and any other capabilities and habits acquired by man as a member of society.” - E.B.Tyler, Primitive Culture(1871) Edward Burnett Tylor (1832-1917) A British anthropologist ‘Primitive Culture’ (1871)"}, {"id": 1, "d": "01", "page": 16, "source": "GCT501_01_Culture and Technology.pdf", "term": "Geert Hofstede", "stem": "Who described culture as “the collective programming of the mind”?", "answer": "Geert Hofstede", "wrong": ["Edward Tylor", "Alan Turing", "John Searle"], "keys": [], "image": null, "kind": "concept", "quote": "“Culture is the collective programming of the mind which distinguishes the members of one group or category of people from another.” Geert Hofstede 1984"}, {"id": 2, "d": "01", "page": 21, "source": "GCT501_01_Culture and Technology.pdf", "term": "Edward T. Hall", "stem": "Who is associated with the Cultural Iceberg Model?", "answer": "Edward T. Hall", "wrong": ["Kevin Kelly", "Carl Mitcham", "Claude Shannon"], "keys": [], "image": null, "kind": "concept", "quote": "The Cultural Iceberg Model Beyond Culture (1976) by Edward T. Hall"}, {"id": 3, "d": "01", "page": 34, "source": "GCT501_01_Culture and Technology.pdf", "term": "Alan Kay", "stem": "Who said “Technology is anything that wasn’t around when you were born”?", "answer": "Alan Kay", "wrong": ["Danny Hillis", "Leo Marx", "Marshall McLuhan"], "keys": [], "image": null, "kind": "concept", "quote": "“Technology is anything that wasn’t around when you were born.”"}, {"id": 4, "d": "01", "page": 35, "source": "GCT501_01_Culture and Technology.pdf", "term": "Danny Hillis", "stem": "Who described technology as something that “doesn’t work yet”?", "answer": "Danny Hillis", "wrong": ["Alan Kay", "Ernst Kapp", "Tim Berners-Lee"], "keys": [], "image": null, "kind": "concept", "quote": "“Technology is a word that describes something that doesn’t work yet.” – Danny Hillis …Technology disappears from our awareness"}, {"id": 5, "d": "01", "page": 50, "source": "GCT501_01_Culture and Technology.pdf", "term": "Technium", "stem": "Who proposed “Technium”?", "answer": "Kevin Kelly", "wrong": ["Ray Kurzweil", "Gordon Moore", "John Searle"], "keys": [], "image": null, "kind": "concept", "quote": "• Proposed by Kevin Kelly • The global, massively interconnected system of technology • Technology as a natural extension of evolution and a natural, living system • (Like biological system) Movement toward ubiquity and complexity is much like the evolution of life • As it evolves, it develops its own dynamics (autonomy)"}, {"id": 6, "d": "02", "page": 7, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Instrumentalism", "stem": "Which position treats technologies as neutral tools whose outcomes depend on human use?", "answer": "Instrumentalism", "wrong": ["Organ Projection", "Social Constructivism", "Background relations"], "keys": [], "image": null, "kind": "concept", "quote": "Technology as a Tool: Instrumentalism • Technologies are neutral • Technological outcomes depend on how the technology is used by humans • Technological progress is unquestionably positive • focuses on • ef ciency and effectiveness to achieve the goal • the problem not the method(technology) itself -> Late appearance (No need) of the philosophy of technology"}, {"id": 7, "d": "02", "page": 16, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Organ Projection", "stem": "Who is associated with Organ Projection?", "answer": "Ernst Kapp", "wrong": ["Don Ihde", "Carl Mitcham", "Marshall McLuhan"], "keys": [], "image": null, "kind": "concept", "quote": "Organ Projection • Humans “project” organs to the outside “humans unconsciously transfer form, function and the normal proportions of their body to the works of “Self-consciousness proves to be the result of a process in which knowledge of an exterior is transformed into knowledge of an interior.” Understanding Self-consciousness"}, {"id": 8, "d": "02", "page": 20, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "The Extensions of Man", "stem": "Who argued that media extend psychic or physical human faculties?", "answer": "Marshall McLuhan", "wrong": ["Ernst Kapp", "John Searle", "Norbert Wiener"], "keys": [], "image": null, "kind": "concept", "quote": "The Extensions of Man • “All media are extensions of some human faculty- psychic or physical.” • Technology as an extension and an enhancement of body and cognitive functions • the wheel the foot the book the eye clothing the skin electric circuitry the central nervous system Understanding Media: The Extensions of Man (1964)"}, {"id": 9, "d": "02", "page": 25, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Four Dimensions of Technology", "stem": "Whose framework includes technology as object, knowledge, activity and volition?", "answer": "Carl Mitcham", "wrong": ["Don Ihde", "Thomas Hughes", "Edward Tylor"], "keys": [], "image": null, "kind": "concept", "quote": "Four Dimensions of Technology (Carl Mitcham) 1. Technology as object 2. Technology as knowledge 3. Technology as action or activity 4. Technology as volition"}, {"id": 10, "d": "02", "page": 29, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Embodiment relations", "stem": "Which relation describes technology becoming part of a human unity directed at the world?", "answer": "Embodiment relations", "wrong": ["Hermeneutic relations", "Alterity relations", "Background relations"], "keys": [], "image": null, "kind": "concept", "quote": "Human-Technology Relations: Embodiment relations • The most intimate couplings between humans and technology • Technologies form a unity with a human being, and this unity is directed at the world (human – technology) —> world"}, {"id": 11, "d": "02", "page": 31, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Hermeneutic relations", "stem": "Which relation involves reading how technology represents the world?", "answer": "Hermeneutic relations", "wrong": ["Embodiment relations", "Background relations", "Alterity relations"], "keys": [], "image": null, "kind": "concept", "quote": "Human-Technology Relations: Hermeneutic relations • Relations in which human beings read/interpret how technologies represent the world • Technologies form a unity with the world • Humans are directed at the ways in which technologies represent the world human —> (technology – world) electron microscope"}, {"id": 12, "d": "02", "page": 32, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Alterity relations", "stem": "Which relation involves technology being encountered as a quasi-other?", "answer": "Alterity relations", "wrong": ["Embodiment relations", "Hermeneutic relations", "Background relations"], "keys": [], "image": null, "kind": "concept", "quote": "Human-Technology Relations: Alterity relations • Alterity: ’otherness' a technology can assume when it is outside normal human experience • Human beings interact with technologies, with the world at the background of this interaction • a central domain of Interaction Design human —> technology (world)"}, {"id": 13, "d": "02", "page": 33, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Background relations", "stem": "Which relation concerns technologies providing the context of experience?", "answer": "Background relations", "wrong": ["Alterity relations", "Embodiment relations", "Hermeneutic relations"], "keys": [], "image": null, "kind": "concept", "quote": "Human-Technology Relations: Background relations • Technologies are the context for human experiences and actions, rather than being experienced themselves human (technology / world)"}, {"id": 14, "d": "02", "page": 37, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Technological Determinism", "stem": "Why is the stirrup–feudal society example included in this section?", "answer": "To illustrate a claim that technology drives social change", "wrong": ["To establish that every invention has identical effects", "To show that social groups never influence technology", "To define sensory immersion"], "keys": [], "image": null, "kind": "concept", "quote": "Examples of Technological Determinism the invention of the stirrup (the 8th century) the development of feudal societies"}, {"id": 15, "d": "02", "page": 51, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Technology System", "stem": "Why discuss Edison’s power system alongside the light bulb?", "answer": "To show that an invention depends on technical and social system elements", "wrong": ["To isolate invention from infrastructure", "To identify the light bulb as a Turing machine", "To reject the role of power distribution"], "keys": [], "image": null, "kind": "concept", "quote": "• Edison and the invention of the light bulb • In addition to the light bulbs, Edison secured technical elements of the power system, such as generators, distributors, .. and founded companies."}, {"id": 16, "d": "02", "page": 53, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Multi-stability", "stem": "What is the teaching point of this ambiguous figure?", "answer": "One configuration can support multiple stable interpretations", "wrong": ["Only one interpretation is possible", "A figure cannot be interpreted culturally", "Technology has a single inevitable use"], "keys": [], "image": "02-53", "kind": "image", "quote": "Multi-stability • What do you see in this gure? • Many things at once; ‘Stable’ in multiple ways: Multi-stability • In the relation between culture and technology • Technology-use context is part of a larger cultural context • Contextuality makes technologies multi- stable (eg. typewriter) The same artefact can have different meanings or identities in different contexts"}, {"id": 17, "d": "03", "page": 9, "source": "GCT501_03_Digital.pdf", "term": "Gottfried Leibniz", "stem": "Which thinker connects binary calculation with an alphabet of human thought in the lecture?", "answer": "Gottfried Leibniz", "wrong": ["John Searle", "Vannevar Bush", "Ted Nelson"], "keys": [], "image": null, "kind": "concept", "quote": "Gottfried Leibniz • German philosopher and mathematician • The founder of computer science • Invention of the binary numerical system (1689) • a system that converts logic verbal statements into a pure mathematical one"}, {"id": 18, "d": "03", "page": 14, "source": "GCT501_03_Digital.pdf", "term": "Claude Shannon", "stem": "Who is associated with Information Theory?", "answer": "Claude Shannon", "wrong": ["Alan Turing", "Gottfried Leibniz", "Douglas Engelbart"], "keys": [], "image": null, "kind": "concept", "quote": "Claude Shannon (1916-2001) • Information Theory • A branch of communications theory • Originated with the work in 1949, \"The Mathematical Basis of Communication” • the problem of how best to encode the message a sender wants to transmit • the foundation for the digital era"}, {"id": 19, "d": "03", "page": 22, "source": "GCT501_03_Digital.pdf", "term": "Information and probability", "stem": "Which event carries more self-information?", "answer": "An event with a lower probability", "wrong": ["An event with certainty", "An event with greater predictability", "Every event carries the same information"], "keys": [], "image": null, "kind": "concept", "quote": "• Information is • inversely proportional to its probability of occurrence • a continuous function of its probability I(x) = log ( 1 / P(x) ) = - log P(x) P(x) : probability of occurrence of x, I(x) : Information"}, {"id": 20, "d": "03", "page": 40, "source": "GCT501_03_Digital.pdf", "term": "Turing Machine", "stem": "What does a Turing machine head do at each time step?", "answer": "Read or write symbols and move along a tape", "wrong": ["Only render pictures", "Only measure network distance", "Only store photographs"], "keys": [], "image": null, "kind": "concept", "quote": "Turing Machine The head at each time step: 1. Reads a symbol 2. Writes a symbol 3. Moves Left or Right In nite length"}, {"id": 21, "d": "03", "page": 45, "source": "GCT501_03_Digital.pdf", "term": "Chinese Room Argument", "stem": "Why is the Chinese Room introduced after machine intelligence?", "answer": "To question whether symbol manipulation is sufficient for understanding", "wrong": ["To demonstrate that syntax guarantees understanding", "To define the Internet", "To measure Shannon entropy directly"], "keys": [], "image": null, "kind": "concept", "quote": "The Chinese Room Argument • proposed by philosopher John Searle in 1980 • A thought experiment countering \"Strong AI,” Questions in Chinese A rulebook written in English Chinese symbols Chinese responses"}, {"id": 22, "d": "03", "page": 54, "source": "GCT501_03_Digital.pdf", "term": "Memex", "stem": "Who proposed Memex in “As we may think”?", "answer": "Vannevar Bush", "wrong": ["Ted Nelson", "John Searle", "Alan Kay"], "keys": [], "image": null, "kind": "concept", "quote": "• By Vannevar Bush (1890-1974) • proposed in “As we may think” (1945) • The theoretical proto-hypertext computer system • Memory extender: An enlarged intimate supplement to his memory"}, {"id": 23, "d": "03", "page": 55, "source": "GCT501_03_Digital.pdf", "term": "Hypertext", "stem": "Who coined Hypertext and Hypermedia?", "answer": "Ted Nelson", "wrong": ["Douglas Engelbart", "Tim Berners-Lee", "Ernst Kapp"], "keys": [], "image": null, "kind": "concept", "quote": "Hypertext, Hypermedia (1963) • Coined by Ted Nelson • Hypertext: non-sequential writing • Project Xanadu (1960)"}, {"id": 24, "d": "03", "page": 56, "source": "GCT501_03_Digital.pdf", "term": "Collective IQ", "stem": "Who is associated with Collective IQ and The Mother of All Demos?", "answer": "Douglas Engelbart", "wrong": ["Ted Nelson", "Claude Shannon", "Alan Turing"], "keys": [], "image": null, "kind": "concept", "quote": "Collective IQ • Douglas Engelbart • The Mother of All Demos (1968): the world's rst interactive information system, NLS (oN Line System) • Collective IQ"}, {"id": 25, "d": "03", "page": 57, "source": "GCT501_03_Digital.pdf", "term": "World Wide Web", "stem": "Who is associated with WWW in the lecture?", "answer": "Tim Berners-Lee", "wrong": ["John Searle", "Vannevar Bush", "Danny Hillis"], "keys": [], "image": null, "kind": "concept", "quote": "Invented by Tim-Berners Lee"}, {"id": 26, "d": "05", "page": 9, "source": "GCT501_05_Pervasive Computing.pdf", "term": "Pervasive Computing", "stem": "Which principle shifts computation toward local or mobile devices?", "answer": "Decentralization", "wrong": ["Centralization", "Mechanical teleology", "Quantitative information"], "keys": [], "image": null, "kind": "concept", "quote": "• Decentralization • Mainframe → Local or mobile devices (Smart phone, Embedded Computers, …) • Networked information • Diversi cation • Universal → (Task) speci c devices • Internet access on huge number of ‘clients’ • Connectivity • Data exchanged between (always-on) devices • Wireless connection / internet • Simplicity • Availability, convenience, easy of use • Seamless interfaces, intuitive, “calm”"}, {"id": 27, "d": "05", "page": 9, "source": "GCT501_05_Pervasive Computing.pdf", "term": "Connectivity", "stem": "Which pervasive computing principle concerns data exchanged between always-on devices?", "answer": "Connectivity", "wrong": ["Volition", "Organ Projection", "Utilitas"], "keys": [], "image": null, "kind": "concept", "quote": "• Decentralization • Mainframe → Local or mobile devices (Smart phone, Embedded Computers, …) • Networked information • Diversi cation • Universal → (Task) speci c devices • Internet access on huge number of ‘clients’ • Connectivity • Data exchanged between (always-on) devices • Wireless connection / internet • Simplicity • Availability, convenience, easy of use • Seamless interfaces, intuitive, “calm”"}, {"id": 28, "d": "06", "page": 3, "source": "GCT501_06_Digital Media and Content (1).pdf", "term": "Media", "stem": "How does this lecture define media?", "answer": "Communication outlets or tools used to store and deliver information or data", "wrong": ["Only the information itself", "Only a physical computer", "Only a commercial platform"], "keys": [], "image": null, "kind": "concept", "quote": "What is Media? • Media are the communication outlets or tools used to store and deliver information or data"}, {"id": 29, "d": "W", "page": 31, "source": "GCT501_Lecture Wrap-up_nobinkan.pdf", "term": "The Medium is the Message", "stem": "Who is associated with “The Medium is the Message”?", "answer": "Marshall McLuhan", "wrong": ["Lev Manovich", "Claude Shannon", "Edward Hall"], "keys": [], "image": null, "kind": "concept", "quote": "“The Medium is the Message.” –Marshall McLuhan"}, {"id": 30, "d": "W", "page": 32, "source": "GCT501_Lecture Wrap-up_nobinkan.pdf", "term": "Medium and cultural change", "stem": "Why focus on the medium itself when discussing cultural change?", "answer": "Its form shapes patterns of human association and action", "wrong": ["All media have the same social effects", "Content determines every property of a medium", "A medium cannot affect perception"], "keys": [], "image": null, "kind": "concept", "quote": "The Medium is the Message • A medium itself, not the content it carries, should be the focus • It is the medium itself that shaped and controlled \"the scale and form of human association and action” • The change of the medium -> the change of the entire cultural model • Technological determinist (Technological determinism) • Formalist (Formalism)"}, {"id": 31, "d": "07", "page": 71, "source": "GCT501_07_VR AR (1).pdf", "term": "Presence", "stem": "Which phrase identifies Presence?", "answer": "Sense of “Being there”", "wrong": ["A count of polygons", "A guarantee of physical immersion", "A measure of bit rate"], "keys": [], "image": null, "kind": "concept", "quote": "• Sense of “Being there” • Virtual presence as a sense of being physically present with visual, auditory, or force displays generated by a computer (Sheridan, 1992) • Telepresence • the experience of presence in an remote environment by means of a communication medium"}, {"id": 32, "d": "07", "page": 73, "source": "GCT501_07_VR AR (1).pdf", "term": "Immersion vs. Presence", "stem": "Which distinction matches the lecture?", "answer": "Immersion concerns sensory delivery; presence concerns a subjective sense of being there", "wrong": ["Presence is identical to screen resolution", "Immersion always guarantees presence", "Presence requires no perceptual experience"], "keys": [], "image": null, "kind": "concept", "quote": "Immersion vs. Presence • Immersion: the extent to which technology delivers a vivid illusion of reality to the senses of a human participant. • Presence: a state of consciousness, the (psychological) sense of being in the virtual • Immersion produces a sense of Presence • Goal of VR: • Create a high degree of Presence • Make people believe they are really in Virtual Environment Slater, M., & Wilbur, S. (1997). A framework for immersive virtual environments (FIVE): Speculations on the role of presence in virtual environments. Presence: Teleoperators and virtual environments, 6(6), 603-616."}, {"id": 33, "d": "07", "page": 77, "source": "GCT501_07_VR AR (1).pdf", "term": "AIP Cube", "stem": "What does AIP stand for?", "answer": "Autonomy, Interaction, Presence", "wrong": ["Architecture, Information, Platform", "Augmentation, Immersion, Probability", "Art, Interface, Perception"], "keys": [], "image": null, "kind": "concept", "quote": "David Zeltzer’s AIP Cube • Autonomy – Virtual object’s ability to act and react to events and stimuli • Interaction – User can interact with objects and environment. • Presence – User feels immersed through sensory input and output channels"}, {"id": 34, "d": "08", "page": 14, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Vitruvius", "stem": "Which triad expresses Vitruvius’ architectural virtues?", "answer": "Utilitas, Firmitas, Venustas", "wrong": ["Autonomy, Interaction, Presence", "Object, Knowledge, Data", "Content, Media, Platform"], "keys": [], "image": null, "kind": "concept", "quote": "Vitruvius’ Virtues of Architecture • The essential components of architectural values: Utilitas (function, commodity, utility), Firmitas (solidity, materiality), and Venustas (beauty, delight, desire)"}, {"id": 35, "d": "08", "page": 20, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Analogue Computation: Antoni Gaudi", "stem": "Why is the physical model shown in this lecture?", "answer": "To demonstrate analogue computation of architectural form", "wrong": ["To demonstrate a purely digital twin", "To show a communication channel", "To define a fashion marker layout"], "keys": [], "image": "08-20", "kind": "image", "quote": "Analogue Computation: Antoni Gaudi • The method of analogue computation using models • The physical model to compute parts of the building to understand the structural and spatial relationships"}, {"id": 36, "d": "08", "page": 24, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Cybernetics", "stem": "Who defined cybernetics through control and communication in the animal and the machine?", "answer": "Norbert Wiener", "wrong": ["John Frazer", "Nicholas Negroponte", "Antoni Gaudi"], "keys": [], "image": null, "kind": "concept", "quote": "• Mid 20th century • \"control and communication in the animal and the machine.” -Norbert Wiener • A mechanism for developing understanding of how humans and machines are controlled by, and can communicate with, one another • First de ned by Norbert Wiener in 1948 Inspired architects"}, {"id": 37, "d": "08", "page": 31, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "BIM", "stem": "What distinguishes BIM from an unstructured geometric drawing?", "answer": "A digital representation of physical and functional building characteristics", "wrong": ["It only stores visible outlines", "It excludes relationships among building elements", "It is limited to hand drawing"], "keys": [], "image": null, "kind": "concept", "quote": "BIM (Building Information Modeling) • Digital representation of physical and functional characteristics of a facility • A shared knowledge resource for information forming a reliable basis for decisions during its life cycle, from earliest conception to demolition"}, {"id": 38, "d": "08", "page": 34, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Generative Design", "stem": "Why use algorithms in generative design?", "answer": "To explore design possibilities under stated goals and constraints", "wrong": ["To remove every design constraint", "To reproduce only one predetermined drawing", "To eliminate all evaluation"], "keys": [], "image": null, "kind": "concept", "quote": "Generative Design • a strategy that uses computer algorithms to analyze and explore all the design possibilities based on speci c goals and constraints • Based on parametric design"}, {"id": 39, "d": "08", "page": 44, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Digital Twin", "stem": "Which definition best matches Digital Twin?", "answer": "A digital counterpart of a real physical product, system or process", "wrong": ["Any unrelated virtual scene", "A flat photograph without further relationship", "A fashion cutting pattern"], "keys": [], "image": null, "kind": "concept", "quote": "• a digital representation of an real-world physical product, system, or process that serves as the effectively indistinguishable digital counterpart of it for practical purposes Cyber-Physical System Realtime Control connection and Monitoring, Analysis, Simulation, Interpretation, Virtual world Prediction, Solution,"}, {"id": 40, "d": "08", "page": 68, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Grading System", "stem": "Which system generates patterns for different sizes and body factors?", "answer": "Grading System", "wrong": ["Marker-making System", "Textile Design System", "AIP Cube"], "keys": [], "image": null, "kind": "concept", "quote": "Grading System • Automatic generation of patterns to sizes and other body factors • Complete automatization is impossible yet"}, {"id": 41, "d": "08", "page": 69, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Marker-making System", "stem": "Why arrange pattern pieces automatically?", "answer": "To maximize the usage of fabric", "wrong": ["To increase cloth waste", "To remove garment sizing", "To model sensory presence"], "keys": [], "image": null, "kind": "concept", "quote": "Marker-making System • Automatic layout of patterns in order to maximize the usage of fabric • Marker-making system -> Plotting machine -> Cutting machine"}, {"id": 42, "d": "08", "page": 75, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Steve Mann", "stem": "Who is called the father of wearable computing?", "answer": "Steve Mann", "wrong": ["Ivan Sutherland", "Alan Turing", "Norbert Wiener"], "keys": [], "image": null, "kind": "concept", "quote": "The father of wearable computing"}, {"id": 43, "d": "08", "page": 82, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Smart Textiles", "stem": "What makes a textile smart in this lecture?", "answer": "Ability to sense, react and adapt to stimuli through integrated functionality", "wrong": ["Its color alone", "Its brand name alone", "Its historical age alone"], "keys": [], "image": null, "kind": "concept", "quote": "Smart Textiles • Textiles that are able to sense stimuli from the environment, to react to them and adapt to them by integration of functionality in the textile structure. The stimulus and response can have an electrical, thermal, chemical, magnetic, or other origin Langenhove, Puers, & Matthys (2005)"}, {"id": 44, "d": "W", "page": 25, "source": "GCT501_Lecture Wrap-up_nobinkan.pdf", "term": "Why Visualization?", "stem": "Why is visualization introduced alongside quantitative analysis?", "answer": "To replace some cognitive tasks with perceptual tasks", "wrong": ["To guarantee that statistics are unnecessary", "To prove all datasets have identical shape", "To avoid examining data"], "keys": [], "image": null, "kind": "concept", "quote": "Why Visualization? • Replace cognition with perception • Cognitive task to perceptive task • Reduces load on working memory Offloads cognition • Uses the power of human perception"}, {"id": 45, "d": "01", "page": 21, "source": "GCT501_01_Culture and Technology.pdf", "term": "Cultural Iceberg Model", "stem": "What does the large submerged region represent?", "answer": "Less visible assumptions and subconscious aspects of culture", "wrong": ["Only visible artifacts", "Only explicit rituals", "Only physical geography"], "keys": [], "image": "01-21", "kind": "image", "quote": "The Cultural Iceberg Model Beyond Culture (1976) by Edward T. Hall"}, {"id": 46, "d": "03", "page": 23, "source": "GCT501_03_Digital.pdf", "term": "Information vs. Probability", "stem": "What explains the downward curve?", "answer": "Higher probability means lower self-information", "wrong": ["Higher probability means greater surprise", "Information is independent of probability", "The graph measures transistor counts"], "keys": [], "image": "03-23", "kind": "image", "quote": "I(x) = - log P(x) Information vs. Probability of Message"}, {"id": 47, "d": "01", "page": 51, "source": "GCT501_01_Culture and Technology.pdf", "term": "Moore’s Law", "stem": "Which quantities are plotted in this original slide?", "answer": "Year of introduction and transistor count", "wrong": ["Time and sensory immersion", "Probability and information", "Fabric size and cost"], "keys": [], "image": "01-51", "kind": "image", "quote": "Moore’s Law (1965)"}, {"id": 48, "d": "07", "page": 76, "source": "GCT501_07_VR AR (1).pdf", "term": "AIP Cube", "stem": "Why represent VR systems with three dimensions?", "answer": "Systems can vary separately in autonomy, interaction and presence", "wrong": ["Every VR system has one fixed quality", "Only graphical realism matters", "Presence alone determines autonomy"], "keys": [], "image": "07-76", "kind": "image", "quote": "AIP Cube (due to Zeltzer, 1992) Zeltzer, D. (1992). Autonomy, interaction, and presence. Presence: Teleoperators & Virtual Environments, 1(1), 127-132."}, {"id": 49, "d": "W", "page": 23, "source": "GCT501_Lecture Wrap-up_nobinkan.pdf", "term": "Anscombe’s Quartet", "stem": "Why discuss these four datasets?", "answer": "Similar summary statistics can conceal different data structures", "wrong": ["Matching means guarantee identical plots", "Correlation proves causality", "Regression makes visualization unnecessary"], "keys": [], "image": "Lecture-23", "kind": "image", "quote": "Anscombe’s Quartet (1973) Linear regression: y = 3 + 0.5x"}, {"id": 50, "d": "03", "page": 23, "source": "GCT501_03_Digital.pdf", "term": "Information graph axes", "stem": "Identify the x-axis and y-axis in the graph. Explain the direction of the curve.", "answer": "x: Probability of Message. y: Information in a Message. Self-information decreases as probability increases; I(x) = −log₂P(x).", "wrong": [], "keys": [["probability", "확률"], ["information", "정보"], ["decreas", "lower", "감소", "작아"]], "image": "03-23", "kind": "written", "quote": "I(x) = - log P(x) Information vs. Probability of Message"}, {"id": 51, "d": "01", "page": 51, "source": "GCT501_01_Culture and Technology.pdf", "term": "Moore’s Law graph axes", "stem": "Identify both axes and the y-axis scale. Explain why a nearly straight trend on this plot is compatible with exponential growth.", "answer": "x: Year of introduction. y: Transistor count on a logarithmic scale. Equal vertical intervals represent multiplication, so exponential growth can appear roughly linear.", "wrong": [], "keys": [["year", "연도"], ["transistor", "트랜지스터"], ["logarithm", "로그"], ["exponential", "지수"]], "image": "01-51", "kind": "written", "quote": "Moore’s Law (1965)"}, {"id": 52, "d": "07", "page": 76, "source": "GCT501_07_VR AR (1).pdf", "term": "AIP Cube dimensions", "stem": "Name the three dimensions of the cube and explain each one.", "answer": "Autonomy is an object’s ability to act and react. Interaction concerns user actions with objects and the environment. Presence concerns the felt experience of being in the environment.", "wrong": [], "keys": [["autonomy", "자율"], ["interaction", "상호작용"], ["presence", "실재감", "현존감"]], "image": "07-76", "kind": "written", "quote": "AIP Cube (due to Zeltzer, 1992) Zeltzer, D. (1992). Autonomy, interaction, and presence. Presence: Teleoperators & Virtual Environments, 1(1), 127-132."}, {"id": 53, "d": "02", "page": 53, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Multi-stability essay", "stem": "Explain Multi-stability using this figure. Connect it to a possible technology use.", "answer": "The figure supports multiple stable interpretations. Likewise, a technology can take on different stable meanings or uses in different human contexts. A well-justified example should connect one artifact to distinct uses.", "wrong": [], "keys": [["multiple", "여러", "다중"], ["interpret", "해석"], ["context", "맥락"]], "image": "02-53", "kind": "written", "quote": "Multi-stability • What do you see in this gure? • Many things at once; ‘Stable’ in multiple ways: Multi-stability • In the relation between culture and technology • Technology-use context is part of a larger cultural context • Contextuality makes technologies multi- stable (eg. typewriter) The same artefact can have different meanings or identities in different contexts"}, {"id": 54, "d": "08", "page": 20, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "Gaudi essay", "stem": "Explain how the shown model serves as analogue computation. Relate the model to architectural form.", "answer": "The physical model uses material forces and equilibrium to work out form. Its geometry helps determine architectural structure, showing computation through physical behavior.", "wrong": [], "keys": [["physical", "물리"], ["form", "형태"], ["force", "equilibrium", "힘", "평형"]], "image": "08-20", "kind": "written", "quote": "Analogue Computation: Antoni Gaudi • The method of analogue computation using models • The physical model to compute parts of the building to understand the structural and spatial relationships"}, {"id": 55, "d": "W", "page": 23, "source": "GCT501_Lecture Wrap-up_nobinkan.pdf", "term": "Anscombe essay", "stem": "Explain why identical or similar summary statistics do not justify skipping visualization.", "answer": "Similar means, variances, correlations and regression lines can accompany different point distributions. Visualization reveals nonlinearity, outliers or other structures hidden by numerical summaries.", "wrong": [], "keys": [["statistic", "mean", "통계", "평균"], ["different", "다른"], ["visual", "plot", "시각", "그래프"]], "image": "Lecture-23", "kind": "written", "quote": "Anscombe’s Quartet (1973) Linear regression: y = 3 + 0.5x"}, {"id": 56, "d": "02", "page": 34, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Technology and society essay", "stem": "Compare Technology Determinism and Social Constructivism. Apply both to the same technology.", "answer": "Technological determinism emphasizes technology driving social change. Social constructivism emphasizes social groups and conditions shaping technology. Apply each explanatory direction to one example and explain its limits.", "wrong": [], "keys": [["technolog", "기술"], ["social", "사회"], ["shape", "drive", "영향", "형성"]], "image": null, "kind": "written", "quote": "Technology Determinism vs. Social Constructivism Technology Determinism Social Constructivism • Technology as being the primary reason • Technology develops as a result of for the growth and progress of a society social, cultural, or economic factors • the exact opposite of technological"}, {"id": 57, "d": "02", "page": 29, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "Human–Technology Relations essay", "stem": "Compare Embodiment relations and Hermeneutic relations with one example each.", "answer": "In embodiment relations, technology mediates perception as part of a human unity, such as glasses. In hermeneutic relations, a user interprets technological representations of the world, such as a thermometer reading.", "wrong": [], "keys": [["embodiment", "체현", "체화"], ["hermeneutic", "해석"], ["example", "glasses", "thermometer", "안경", "온도계", "예"]], "image": null, "kind": "written", "quote": "Human-Technology Relations: Embodiment relations • The most intimate couplings between humans and technology • Technologies form a unity with a human being, and this unity is directed at the world (human – technology) —> world"}, {"id": 58, "d": "07", "page": 73, "source": "GCT501_07_VR AR (1).pdf", "term": "Immersion and presence essay", "stem": "Explain why stronger sensory immersion might not always produce stronger presence.", "answer": "Immersion concerns what the system delivers to the senses. Presence is a subjective sense of being there, also influenced by believable interaction and the coherence of experience. The two are related but need not increase identically.", "wrong": [], "keys": [["immersion", "몰입"], ["presence", "실재감", "현존감"], ["subjective", "주관"]], "image": null, "kind": "written", "quote": "Immersion vs. Presence • Immersion: the extent to which technology delivers a vivid illusion of reality to the senses of a human participant. • Presence: a state of consciousness, the (psychological) sense of being in the virtual • Immersion produces a sense of Presence • Goal of VR: • Create a high degree of Presence • Make people believe they are really in Virtual Environment Slater, M., & Wilbur, S. (1997). A framework for immersive virtual environments (FIVE): Speculations on the role of presence in virtual environments. Presence: Teleoperators and virtual environments, 6(6), 603-616."}, {"id": 59, "d": "08", "page": 31, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "BIM and Digital Twin essay", "stem": "Compare BIM and Digital Twin. Explain why their relationship must be specified for a building project.", "answer": "BIM represents a building’s physical and functional characteristics and related information. A digital twin is a counterpart of a specific physical system or process. A project should state the real-world counterpart and how the model is used.", "wrong": [], "keys": [["BIM"], ["physical", "물리"], ["counterpart", "대응", "실물"]], "image": null, "kind": "written", "quote": "BIM (Building Information Modeling) • Digital representation of physical and functional characteristics of a facility • A shared knowledge resource for information forming a reliable basis for decisions during its life cycle, from earliest conception to demolition"}, {"id": 60, "d": "01", "page": 21, "source": "GCT501_01_Culture and Technology.pdf", "term": "Cultural Iceberg essay", "stem": "Explain how the Cultural Iceberg Model could inform an ethnographic design study.", "answer": "Visible artifacts and practices do not exhaust culture. A study should investigate underlying values and assumptions through contextual observation and questions, then relate findings to design decisions.", "wrong": [], "keys": [["visible", "가시", "보이는"], ["value", "assumption", "가치", "가정"], ["observ", "관찰"]], "image": "01-21", "kind": "written", "quote": "The Cultural Iceberg Model Beyond Culture (1976) by Edward T. Hall"}, {"id": 61, "d": "03", "page": 45, "source": "GCT501_03_Digital.pdf", "term": "Chinese Room essay", "stem": "Explain the target of the Chinese Room Argument and distinguish syntax from understanding.", "answer": "Searle questions whether manipulating symbols according to rules is sufficient for understanding. Syntax concerns formal symbol operations; understanding involves meaning. The argument challenges the sufficiency claimed by Strong AI.", "wrong": [], "keys": [["symbol", "기호"], ["understand", "이해"], ["meaning", "의미"]], "image": null, "kind": "written", "quote": "The Chinese Room Argument • proposed by philosopher John Searle in 1980 • A thought experiment countering \"Strong AI,” Questions in Chinese A rulebook written in English Chinese symbols Chinese responses"}, {"id": 62, "d": "02", "page": 25, "source": "GCT501_02_Philosophy of Technology (1).pdf", "term": "People and concepts", "stem": "Match A–E to 1–5. Select the complete correct mapping.", "answer": "A–1, B–2, C–3, D–4, E–5", "wrong": ["A–2, B–1, C–3, D–4, E–5", "A–1, B–3, C–2, D–5, E–4", "A–5, B–4, C–3, D–2, E–1"], "keys": [], "image": null, "kind": "matching", "quote": "Four Dimensions of Technology (Carl Mitcham) 1. Technology as object 2. Technology as knowledge 3. Technology as action or activity 4. Technology as volition", "pairs": [["Ernst Kapp", "Organ Projection"], ["Marshall McLuhan", "The Extensions of Man"], ["Carl Mitcham", "Four Dimensions of Technology"], ["Don Ihde", "Human–Technology Relations"], ["Thomas Hughes", "Technology System"]], "pages": [16, 20, 25, 28, 49]}, {"id": 63, "d": "03", "page": 55, "source": "GCT501_03_Digital.pdf", "term": "People and concepts", "stem": "Match A–E to 1–5. Select the complete correct mapping.", "answer": "A–1, B–2, C–3, D–4, E–5", "wrong": ["A–2, B–1, C–3, D–4, E–5", "A–1, B–3, C–2, D–5, E–4", "A–5, B–4, C–3, D–2, E–1"], "keys": [], "image": null, "kind": "matching", "quote": "Hypertext, Hypermedia (1963) • Coined by Ted Nelson • Hypertext: non-sequential writing • Project Xanadu (1960)", "pairs": [["Claude Shannon", "Information Theory"], ["Alan Turing", "Turing Machine"], ["John Searle", "The Chinese Room Argument"], ["Vannevar Bush", "Memex"], ["Ted Nelson", "Hypertext"]], "pages": [14, 40, 45, 54, 55]}, {"id": 64, "d": "01", "page": 21, "source": "GCT501_01_Culture and Technology.pdf", "term": "People and concepts", "stem": "Match A–E to 1–5. Select the complete correct mapping.", "answer": "A–1, B–2, C–3, D–4, E–5", "wrong": ["A–2, B–1, C–3, D–4, E–5", "A–1, B–3, C–2, D–5, E–4", "A–5, B–4, C–3, D–2, E–1"], "keys": [], "image": null, "kind": "matching", "quote": "The Cultural Iceberg Model Beyond Culture (1976) by Edward T. Hall", "pairs": [["Edward Tylor", "Culture as a complex whole"], ["Geert Hofstede", "Collective programming of the mind"], ["Edward T. Hall", "The Cultural Iceberg Model"], ["Kevin Kelly", "Technium"], ["Ray Kurzweil", "The Law of Accelerating Returns"]], "pages": [12, 16, 21, 50, 54]}, {"id": 65, "d": "08", "page": 24, "source": "GCT501_08_Digital Architecture and Digital Fashion.pdf", "term": "People and concepts", "stem": "Match A–E to 1–5. Select the complete correct mapping.", "answer": "A–1, B–2, C–3, D–4, E–5", "wrong": ["A–2, B–1, C–3, D–4, E–5", "A–1, B–3, C–2, D–5, E–4", "A–5, B–4, C–3, D–2, E–1"], "keys": [], "image": null, "kind": "matching", "quote": "• Mid 20th century • \"control and communication in the animal and the machine.” -Norbert Wiener • A mechanism for developing understanding of how humans and machines are controlled by, and can communicate with, one another • First de ned by Norbert Wiener in 1948 Inspired architects", "pairs": [["Vitruvius", "Utilitas, Firmitas, Venustas"], ["Antoni Gaudi", "Analogue Computation"], ["Norbert Wiener", "Cybernetics"], ["Nicholas Negroponte", "The Architecture Machine"], ["Steve Mann", "Wearable Computing"]], "pages": [14, 20, 24, 25, 75]}, {"id": 66, "d": "10", "page": 5, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Tangible and Intangible Heritage", "stem": "Which item belongs to intangible cultural heritage?", "answer": "Oral traditions", "wrong": ["A manuscript", "An archaeological site", "A coin"], "keys": [], "image": null, "kind": "concept", "quote": "Cultural Heritage Tangible cultural heritage: movable cultural heritage (paintings, sculptures, coins, manuscripts) immovable cultural heritage (monuments, archaeological sites, and so on) underwater cultural heritage (shipwrecks, underwater ruins and cities) Intangible cultural heritage: oral traditions, performing arts, rituals"}, {"id": 67, "d": "10", "page": 15, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Conservation", "stem": "What is the purpose of conservation in this lecture?", "answer": "To sustain a heritage resource’s values and cultural significance", "wrong": ["To return every resource to a conjectured original appearance", "To replace all existing fabric with new materials", "To discard its social significance"], "keys": [], "image": null, "kind": "concept", "quote": "• All the processes of looking after a heritage resource so as to sustain its values and its cultural signi cance. • Cultural signi cance: aesthetic, historic, scienti c, social or spiritual value, for present and future generations • Conservation activities include examination, documentation, treatment, and preventive care, supported by research and education. • The aim is to maintain the physical and cultural characteristics of the object or the site to ensure that its value is not diminished and that it will outlive our limited time span"}, {"id": 68, "d": "10", "page": 16, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Restoration", "stem": "Which condition is specified in the slide definition of restoration?", "answer": "Return to a previously known state without conjecture or new materials in the existing fabric", "wrong": ["Invent a plausible state without evidence", "Replace all original material", "Treat every virtual model as a physical repair"], "keys": [], "image": null, "kind": "concept", "quote": "• A form of repair that returns a heritage resource to a previously known state, done without any conjecture, and without the introduction of new materials to the existing"}, {"id": 69, "d": "10", "page": 19, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Documentation", "stem": "What does documentation record in a permanent format?", "answer": "Information derived from conservation activities", "wrong": ["Only projected tourism revenue", "Only a visitor’s preference", "Only speculative reconstructions"], "keys": [], "image": null, "kind": "concept", "quote": "Documentation • The recording in a permanent format of information derived from conservation activities. • Recording is the capture of information which describes the physical con guration, condition and use of monuments, groups of buildings and sites, at points in time and it is an essential part of the conservation process. – ICOMOS (1996) Research, Record, Conservation Conservation Conservation work Post conservation Survey, Analysis project Documentation Documentation Documentation Documentation at before conservation after conservation intervention work"}, {"id": 70, "d": "10", "page": 22, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Born-Digital", "stem": "Which resource is born-digital?", "answer": "A resource with no other original format but the digital object", "wrong": ["A stone carving photographed later", "A printed book scanned later", "An analogue film digitized later"], "keys": [], "image": null, "kind": "concept", "quote": "“there is no other format but the digital object” “Digital materials include texts, databases, still and moving images, audio, graphics, software and web pages, among a wide and growing range of formats.”"}, {"id": 71, "d": "10", "page": 23, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Digitization", "stem": "Which operation describes digitization?", "answer": "Converting a continuous analogue signal into a discrete digital signal", "wrong": ["Converting every digital file into stone", "Replacing documentation with conjecture", "Making every artifact physically smaller"], "keys": [], "image": null, "kind": "concept", "quote": "• Convert a continuous analogue signal into a discrete digital signal A Book Scanner Smithsonian X 3D International Dunhuang Project at British Library Google Art Project"}, {"id": 72, "d": "10", "page": 37, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Digital Documentation", "stem": "What is the central aim of digital documentation?", "answer": "To measure and record cultural and natural heritage", "wrong": ["To recreate lost sites without any records", "To increase display brightness alone", "To substitute all physical conservation"], "keys": [], "image": null, "kind": "concept", "quote": "Digital Documentation • The use of digital tools and technologies to measure and record cultural and natural heritage • Introduction of digital-based metric survey • precise and large data • analysis and application in new way • re-use of output in digital format for various purpose • accessibility through network"}, {"id": 73, "d": "10", "page": 44, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Digital Reconstruction", "stem": "Which example best fits digital reconstruction?", "answer": "Using 3D graphics to visualize a damaged or lost historic site", "wrong": ["Capturing only a visitor’s ticket", "Replacing a database with a printed label", "Destroying existing documentation"], "keys": [], "image": null, "kind": "concept", "quote": "Digital Reconstruction • Virtually reconstruct and visualize damaged or lost historic sites using 3D graphics"}, {"id": 74, "d": "10", "page": 57, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Digital Restoration", "stem": "What distinguishes digital restoration as defined here?", "answer": "Digitizing damaged material and applying restoration techniques in the digital domain", "wrong": ["Physically repainting every original surface", "Inventing history without evidence", "Using only analogue recording"], "keys": [], "image": null, "kind": "concept", "quote": "Digital Restoration • Actual restoration in digital domain • Digitize a damaged material then apply a digital-based restoration technique • Restoration of a digitized material by using various algorithm is easier than a physical restoration (eg. Photos, Books, …) • Useful when the result of digital restoration can substitute the original • Simulation of physical restoration in a virtual space"}, {"id": 75, "d": "10", "page": 66, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "ARCHEOGUIDE", "stem": "Why is ARCHEOGUIDE included under AR at historic sites?", "answer": "It illustrates on-site cultural heritage interpretation using augmented reality", "wrong": ["It illustrates a purely paper archive", "It defines the transistor count axis", "It replaces every historic site with a theme park"], "keys": [], "image": null, "kind": "concept", "quote": "AR at the Historic Sites ARCHEOGUIDE (AR based Cultural Heritage On-site GUIDE) Vlahakis, V. et al. (2001)"}, {"id": 76, "d": "10", "page": 82, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Museum as Information", "stem": "What is the point of “The Smithsonian is Information”?", "answer": "Objects are selected because they convey information", "wrong": ["Objects have no interpretive role", "Only computers can communicate meaning", "Museums cannot use texts"], "keys": [], "image": null, "kind": "concept", "quote": "The Smithsonian is Information. Museums select objects because they convey information. Artifacts, specimens, models, paintings, photographs and texts all are chosen because they convey information through their uniqueness or representativeness, historical signi cance, or their aesthetic appeal. - Lytle, Director of Smithsonian Institute Archives(1981) Recognition of the importance of Information-centered institution Information Technology the information in the museum Information explosion in the 1990s"}, {"id": 77, "d": "10", "page": 93, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "André Malraux", "stem": "Who is associated with “An art book is a museum without walls”?", "answer": "André Malraux", "wrong": ["Marshall McLuhan", "Ernst Kapp", "Carl Mitcham"], "keys": [], "image": null, "kind": "concept", "quote": "“An art book is a museum without walls.” “The history of art for the last hundred years is the history what can be photographed.” –André Malraux"}, {"id": 78, "d": "10", "page": 95, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Virtual Museum", "stem": "How does the lecture qualify an online-only definition of a virtual museum?", "answer": "Virtual museums can also complement physical museums", "wrong": ["Virtual museums must exclude physical museums", "Every virtual museum is a physical collection store", "Online access is irrelevant to every definition"], "keys": [], "image": null, "kind": "concept", "quote": "De nition of Virtual Museum • This de nition emphasizes the characteristic \"online\" of virtual museums • Virtual museum • as a virtual complement to the physical museum • as a museum in its own right"}, {"id": 79, "d": "10", "page": 59, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "In-Painting", "stem": "Which process is illustrated on this slide?", "answer": "Filling missing image regions in digital restoration", "wrong": ["Increasing transistor density", "Measuring sensory presence", "Projecting body organs"], "keys": [], "image": "10-59", "kind": "image", "quote": "Ciortan, I. M., George, S., & Hardeberg, J. Y. (2021). Colour- balanced edge-guided digital inpainting: Applications on artworks. Sensors, 21(6), 2091."}, {"id": 80, "d": "10", "page": 69, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Projection based AR", "stem": "Why is Saint Climent de Taüll shown in this section?", "answer": "To illustrate projecting interpretive imagery onto a historic physical setting", "wrong": ["To illustrate born-digital text only", "To illustrate Moore’s Law", "To illustrate an isolated database schema"], "keys": [], "image": "10-69", "kind": "image", "quote": "Projection based AR Saint Climent de Taüll"}, {"id": 81, "d": "10", "page": 4, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Heritage Cycle", "stem": "Explain how the stages in the shown Heritage Cycle are related. Describe a plausible feedback loop.", "answer": "Understanding heritage can lead to valuing it, caring for it and enjoying it. Enjoyment can stimulate further understanding, so conservation can participate in a continuing cycle. The example should link stages rather than list them.", "wrong": [], "keys": [["understand", "理解", "이해"], ["valu", "가치"], ["car", "보호", "보존"], ["enjoy", "향유", "즐"]], "image": "10-4", "kind": "written", "quote": "Heritage Cycle"}, {"id": 82, "d": "10", "page": 44, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Documentation vs. Reconstruction", "stem": "Compare digital documentation and digital reconstruction. Explain how evidence affects a reconstructed model.", "answer": "Digital documentation measures and records heritage. Digital reconstruction uses 3D graphics to visualize damaged or lost historic settings. A reconstruction should relate its claims to records and distinguish supported features from uncertain interpretations.", "wrong": [], "keys": [["record", "기록"], ["reconstruct", "복원", "재구성"], ["evidence", "record", "근거", "기록"]], "image": null, "kind": "written", "quote": "Digital Reconstruction • Virtually reconstruct and visualize damaged or lost historic sites using 3D graphics"}, {"id": 83, "d": "10", "page": 57, "source": "GCT501_10_Digital Heritage and Digital Museum(1).pdf", "term": "Digital restoration essay", "stem": "Distinguish restoring a digitized image from physically restoring the original object. Why does the distinction matter?", "answer": "Digital restoration operates on a digital representation of damaged material. Physical restoration changes the material resource. A digital result can support analysis and interpretation while the physical original retains its existing condition.", "wrong": [], "keys": [["digital", "디지털"], ["physical", "물리", "실물"], ["represent", "표현", "재현", "대상"]], "image": null, "kind": "written", "quote": "Digital Restoration • Actual restoration in digital domain • Digitize a damaged material then apply a digital-based restoration technique • Restoration of a digitized material by using various algorithm is easier than a physical restoration (eg. Photos, Books, …) • Useful when the result of digital restoration can substitute the original • Simulation of physical restoration in a virtual space"}, {"id": 84, "d": "09", "page": 4, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Georges Braque", "stem": "Who said “Art is meant to disturb, science reassures”?", "answer": "Georges Braque", "wrong": ["Albert Einstein", "John Lasseter", "Leonardo da Vinci"], "keys": [], "image": null, "kind": "concept", "quote": "–Georges Braque “Art is meant to disturb, science reassures.”"}, {"id": 85, "d": "09", "page": 5, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Albert Einstein", "stem": "Who connected the mysterious with the source of true art and science?", "answer": "Albert Einstein", "wrong": ["Georges Braque", "John Lasseter", "Ernst Kapp"], "keys": [], "image": null, "kind": "concept", "quote": "“The most beautiful thing we can experience is the mysterious. It is the source of all true art and science,” –Albert Einstein"}, {"id": 86, "d": "09", "page": 7, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "John Lasseter", "stem": "Who said “The art challenges the technology, and the technology inspires the art”?", "answer": "John Lasseter", "wrong": ["Georges Braque", "Albert Einstein", "Carl Mitcham"], "keys": [], "image": null, "kind": "concept", "quote": "the technology inspires the art.” –John Lasseter “The art challenges the technology, and"}, {"id": 87, "d": "09", "page": 9, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Visual Culture", "stem": "What does the lecture associate with visual culture?", "answer": "Visualization of a culture’s values and beliefs through various means", "wrong": ["Only paintings inside museums", "Only digital screen resolution", "Only the physiology of the eye"], "keys": [], "image": null, "kind": "concept", "quote": "Visual Culture • Visual + Culture: the visualization, through various means, of the values and beliefs of a culture Barnard, M. (1998) • A form of life based on the visible; a cultural pattern emphasis toward images and screens, with predominance of visual forms of communication and information. Barroso, P. M. (2020) Human culture based on visual media — pictures, sculpture, and (sometimes) dance— as opposed to oral culture and print culture, based on language, words, and writing. New World Encyclopedia • A tactic for studying the functions of a world addressed through pictures, images, and visualizations, rather than through texts and words."}, {"id": 88, "d": "09", "page": 27, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Brunelleschi’s Experiment", "stem": "Why discuss Brunelleschi’s experiment in this sequence?", "answer": "To connect perspective construction with representing spatial reality on a plane", "wrong": ["To introduce wearable textile sensors", "To define Shannon information", "To prove all images are photographic"], "keys": [], "image": null, "kind": "concept", "quote": "Brunelleschi’s Experiment (1425)"}, {"id": 89, "d": "09", "page": 29, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Leon Battista Alberti", "stem": "Who published Della pittura (On Painting) in 1435?", "answer": "Leon Battista Alberti", "wrong": ["Albrecht Dürer", "Paul Cézanne", "Filippo Brunelleschi"], "keys": [], "image": null, "kind": "concept", "quote": "Leon Battsta Alberti published Della pittura(English: \"On Painting”,1435)"}, {"id": 90, "d": "09", "page": 32, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Albrecht Dürer", "stem": "Who is associated with the perspective machine in The Painter’s Manual (1525)?", "answer": "Albrecht Dürer", "wrong": ["Leon Battista Alberti", "Claude Monet", "Georges Seurat"], "keys": [], "image": null, "kind": "concept", "quote": "illustration of a perspective machine in The Painter's Manual (1525) by Albrecht Dürer"}, {"id": 91, "d": "09", "page": 47, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Camera Obscura", "stem": "Which term combines words meaning dark and room?", "answer": "Camera Obscura", "wrong": ["Camera Lucida", "View frustum", "Plenoptic Function"], "keys": [], "image": null, "kind": "concept", "quote": "Camera Obscura obscure (dark) + camera(room)"}, {"id": 92, "d": "09", "page": 50, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Camera Lucida", "stem": "Which term is translated as “well-lit room” on the slide?", "answer": "Camera Lucida", "wrong": ["Camera Obscura", "Neural Radiance Field", "Digital Twin"], "keys": [], "image": null, "kind": "concept", "quote": "Camera Lucida Latin \"well-lit room”"}, {"id": 93, "d": "09", "page": 53, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Hockney-Falco Thesis", "stem": "How does the lecture characterize the Hockney-Falco Thesis?", "answer": "A controversial art-history theory linking advances in realism with optical assistance", "wrong": ["An established proof that every painting used a camera", "A theory of transistor growth", "A theory of ubiquitous networking"], "keys": [], "image": null, "kind": "concept", "quote": "Hockney-Falco Thesis (2001) • a controversial theory of art history, advanced by artist David Hockney and physicist Charles M. Falco • Advances in realism and accuracy in the history of Western art since the Renaissance were primarily the result of optical aids (e.g. the camera obscura, camera lucida, and curved mirrors)"}, {"id": 94, "d": "09", "page": 67, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Metal Paint Tube", "stem": "Why show a metal paint tube near the discussion of Impressionism?", "answer": "To connect material tools and painting practices", "wrong": ["To define a communication channel mathematically", "To measure a virtual object’s autonomy", "To identify a logarithmic axis"], "keys": [], "image": null, "kind": "concept", "quote": "Metal Paint Tube"}, {"id": 95, "d": "09", "page": 72, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Michel Eugène Chevreul", "stem": "Who wrote The Principles of Harmony and Contrast of Colors?", "answer": "Michel Eugène Chevreul", "wrong": ["Isaac Newton", "Paul Cézanne", "Albrecht Dürer"], "keys": [], "image": null, "kind": "concept", "quote": "• “The Principles of Harmony and Contrast of Colors” by Michel Eugène Chevreul • Primary colors, Complementary colors Charles Henry Michel Eugène Chevreul"}, {"id": 96, "d": "09", "page": 102, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Modernism", "stem": "Which shift in art is summarized on the Modernism slide?", "answer": "Representation to Interpretation", "wrong": ["Interpretation to transistor counting", "Digitization to movable type", "Immersion to fixed probability"], "keys": [], "image": null, "kind": "concept", "quote": "Art Representation Interpretation Science Absolute/Certainty Relative/Uncertainty Technology Machinery/Force Electricity/Energy Society Rational/Simplicity Irrational/Complexity"}, {"id": 97, "d": "09", "page": 115, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Rendering", "stem": "Which question frames image generation in this lecture?", "answer": "What color is this pixel?", "wrong": ["Who owns this server?", "How heavy is this building?", "How many visitors bought a ticket?"], "keys": [], "image": null, "kind": "concept", "quote": "“What color is this pixel?”"}, {"id": 98, "d": "09", "page": 116, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Plenoptic Function", "stem": "Which phrase describes the plenoptic function on the slide?", "answer": "The set of things one can ever see", "wrong": ["The set of all cultural institutions", "The number of bits in every message", "A database of architectural components"], "keys": [], "image": null, "kind": "concept", "quote": "2, Light as a Function: Light Field • The Plenoptic Function, “The set of things one can ever see” • plenus (Latin for “full”) + optic (Greek for “seeing”) • Adelson and Bergen in the early 1990s • Light intensity as a 7-D function of viewpoint (position and direction), time, and wavelength • Simplification: 5D Plenoptic Function, 4D Light Field (M. Levoy, S.J.Gortler et al.)"}, {"id": 99, "d": "09", "page": 118, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "NeRF", "stem": "What is a goal of NeRF as presented here?", "answer": "Synthesizing novel views from input views by optimizing a continuous volumetric scene function", "wrong": ["Increasing the physical size of a camera lens", "Classifying only garment sizes", "Replacing all scene properties with text labels"], "keys": [], "image": null, "kind": "concept", "quote": "NeRF (Neural Radiance Field) • A method for synthesizing novel views of complex scenes by optimizing an underlying continuous volumetric scene function using a sparse set of input views."}, {"id": 100, "d": "09", "page": 119, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Neural Rendering", "stem": "How is neural rendering described?", "answer": "Using deep neural networks to create images or video while controlling scene properties", "wrong": ["Printing every model before viewing it", "A purely mechanical painting grid", "A theory restricted to analogue oscilloscopes"], "keys": [], "image": null, "kind": "concept", "quote": "Neural Rendering • A method based on deep neural networks to create new images and video footage by explicitly or implicitly controlling scene properties. • Inverse Rendering: Estimating unique scene properties given a single photo or set of photos of a scene • Novel view synthesis: neural networks learn to render a scene from an arbitrary point of view"}, {"id": 101, "d": "09", "page": 126, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Gaussian Splatting", "stem": "How does the slide describe the scene representation?", "answer": "A set of Gaussians with parameters calculated by machine learning", "wrong": ["A single printed sheet without depth", "Only a list of philosopher names", "Only a transistor count"], "keys": [], "image": null, "kind": "concept", "quote": "Gaussian Splatting • The 3D space is defined as a set of Gaussians, and each Gaussian's parameters are calculated by machine learning • Position(X,Y,Z), Covariance(stretched/scaled)(3x3 matrix), The Gaussian function Color(RGB), Alpha(transparency)(α)"}, {"id": 102, "d": "09", "page": 135, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Ben F. Laposky", "stem": "Who is associated with Oscillons or Electronic Abstractions?", "answer": "Ben F. Laposky", "wrong": ["Georg Nees", "Frieder Nake", "Harold Cohen"], "keys": [], "image": null, "kind": "concept", "quote": "Ben F. Laposky • a mathematician, credited with making the first computer graphics • Oscillons or Electronic Abstractions Ben F Laposky in action"}, {"id": 103, "d": "09", "page": 139, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Digital Computer Graphics", "stem": "Which group is listed as pioneers of digital computer graphics?", "answer": "A. Michael Noll, Georg Nees and Frieder Nake", "wrong": ["Ernst Kapp, Don Ihde and Carl Mitcham", "Edward Tylor, Geert Hofstede and Edward Hall", "Vitruvius, Gaudi and Wiener"], "keys": [], "image": null, "kind": "concept", "quote": "The pioneers: • Digital Computer Graphics A. Michael Noll, Georg Nees and Frieder Nake"}, {"id": 104, "d": "09", "page": 152, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Eduardo Kac", "stem": "Who made GFP Bunny (2000)?", "answer": "Eduardo Kac", "wrong": ["Nam June Paik", "Stelarc", "Harold Cohen"], "keys": [], "image": null, "kind": "concept", "quote": "GFP Bunny (2000) by Eduardo Kac *GFP(green fluorescent protein)"}, {"id": 105, "d": "09", "page": 164, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Technology as a collaborator", "stem": "Why is AARON by Harold Cohen placed under this heading?", "answer": "To discuss technology as a collaborator in artistic production", "wrong": ["To define technology only as a passive display surface", "To describe a perspective camera alone", "To illustrate a textile grading system"], "keys": [], "image": null, "kind": "concept", "quote": "a collaborator Technology as Aaron by Harold Cohen"}, {"id": 106, "d": "09", "page": 22, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Perspective and orthogonal lines", "stem": "What is the teaching role of the lines superimposed on this painting?", "answer": "To make the construction of perspective explicit", "wrong": ["To show Shannon entropy", "To show a textile weave", "To measure transistor counts"], "keys": [], "image": "09-22", "kind": "image", "quote": "The Holy Trinity with orthogonal lines"}, {"id": 107, "d": "09", "page": 40, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "View frustum and image plane", "stem": "What relationship does this diagram help explain?", "answer": "Projection of a three-dimensional scene onto a two-dimensional image plane", "wrong": ["A five-person concept matching table", "A heritage conservation budget", "A plot of year versus transistor count"], "keys": [], "image": "09-40", "kind": "image", "quote": "Virtual object Virtual camera"}, {"id": 108, "d": "09", "page": 142, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Mondrian and Noll", "stem": "Why place these two works side by side?", "answer": "To compare an artwork with a computer-generated composition and raise questions about artistic production", "wrong": ["To claim the works were made by the same person", "To compare two historic clothing patterns", "To define architectural BIM"], "keys": [], "image": "09-142", "kind": "image", "quote": "P. Mondrian “Composition With Lines”, 1917; A. Michael Noll “Computer Composition With Lines”, 1965"}, {"id": 109, "d": "09", "page": 40, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Projection diagram essay", "stem": "Explain the roles of the virtual object, image plane and view frustum in this diagram.", "answer": "The virtual object belongs to the scene. Projection maps it onto the image plane. The view frustum defines the viewing volume associated with the perspective view. Explain the relationship rather than treating the image plane as the physical object.", "wrong": [], "keys": [["object", "물체", "객체"], ["image plane", "영상면", "이미지 평면", "투영면"], ["frustum", "절두체", "시야"]], "image": "09-40", "kind": "written", "quote": "Virtual object Virtual camera"}, {"id": 110, "d": "09", "page": 53, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Hockney-Falco essay", "stem": "Explain the Hockney-Falco Thesis and why its status matters when using it to interpret a painting.", "answer": "The thesis proposes optical assistance as a factor in advances in realism and accuracy in Western painting. The lecture calls it controversial. A response should distinguish the proposed explanation from established evidence for a particular artwork.", "wrong": [], "keys": [["optic", "광학"], ["realis", "사실", "정확"], ["controvers", "논쟁", "논란"]], "image": null, "kind": "written", "quote": "Hockney-Falco Thesis (2001) • a controversial theory of art history, advanced by artist David Hockney and physicist Charles M. Falco • Advances in realism and accuracy in the history of Western art since the Renaissance were primarily the result of optical aids (e.g. the camera obscura, camera lucida, and curved mirrors)"}, {"id": 111, "d": "09", "page": 102, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "Modernism essay", "stem": "Compare the changes summarized for art, science and technology on the Modernism slide.", "answer": "The slide contrasts representation with interpretation in art, absolute or certainty with relative or uncertainty in science, and machinery or force with electricity or energy in technology. These are the lecture’s broad interpretive comparisons and should not be treated as identical causal laws.", "wrong": [], "keys": [["interpret", "해석"], ["relative", "uncertain", "상대", "불확실"], ["electric", "energy", "전기", "에너지"]], "image": null, "kind": "written", "quote": "Art Representation Interpretation Science Absolute/Certainty Relative/Uncertainty Technology Machinery/Force Electricity/Energy Society Rational/Simplicity Irrational/Complexity"}, {"id": 112, "d": "09", "page": 118, "source": "GCT501_09_AST Interaction in the Visual Culture-압축됨.pdf", "term": "NeRF and Gaussian Splatting essay", "stem": "Compare how NeRF and Gaussian Splatting represent a scene in this lecture.", "answer": "NeRF optimizes a continuous volumetric scene function from input views to synthesize new views. Gaussian Splatting represents space as a set of Gaussians with learned parameters. Both relate captured views to renderable scene representations, using different representations.", "wrong": [], "keys": [["continuous", "연속"], ["gaussian", "가우시안"], ["view", "시점"]], "image": null, "kind": "written", "quote": "NeRF (Neural Radiance Field) • A method for synthesizing novel views of complex scenes by optimizing an underlying continuous volumetric scene function using a sparse set of input views."}];const IMAGES={"07-76": "data:image/jpeg;base64,", "01-51": "data:image/jpeg;base64,", "02-53": "data:image/jpeg;base64,", "03-23": "data:image/jpeg;base64,", "Lecture-23": "data:image/jpeg;base64,", "01-54": "data:image/jpeg;base64,", "01-21": "data:image/jpeg;base64,", "08-20": "data:image/jpeg;base64,", "10-4": "data:image/jpeg;base64,", "10-59": "data:image/jpeg;base64,", "10-69": "data:image/jpeg;base64,", "09-22": "data:image/jpeg;base64,", "09-40": "data:image/jpeg;base64,", "09-142": "data:image/jpeg;base64,"};